After converting the difference into a subset target, this version uses a full two-dimensional table. `dp[i][s]` stores the number of ways to make sum `s` using the first `i` values. This is easier to inspect than the compressed one-dimensional form, though it needs more memory.

```java
class Solution {
 public int countPartitions(int n, int diff, int[] arr) {
        final int MOD = 1000000007;
        long total = 0;
        for (int value : arr) {
            total += value;
        }

        long needed = total + diff;
        if (needed < 0 || needed % 2 != 0) {
            return 0;
        }

        int target = (int) (needed / 2);
        int[][] dp = new int[n + 1][target + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            int value = arr[i - 1];
            for (int sum = 0; sum <= target; sum++) {
                dp[i][sum] = dp[i - 1][sum];
                if (sum >= value) {
                    dp[i][sum] += dp[i - 1][sum - value];
                    if (dp[i][sum] >= MOD) {
                        dp[i][sum] -= MOD;
                    }
                }
            }
        }

        return dp[n][target];
    }
}
```

The important invalid cases are an odd value of `total + diff`, or a target larger than the total. Both mean that no partition can match the requested difference. Zero values are handled by the two choices in the transition.

Time complexity: `O(n * target)`.
Space complexity: `O(n * target)`.

The difference between the two group sums gives a target subset sum:

`sum1 - sum2 = diff` and `sum1 + sum2 = total`

So, `sum1 = (total + diff) / 2`. I count how many subsets have this sum. A one-dimensional DP array is enough, and processing sums from right to left prevents using the same element twice.

```cpp
class Solution {
  public:
   int countPartitions(int n, int diff, vector<int>& arr) {
        const int MOD = 1000000007;
        long long total = 0;
        for (int value : arr) {
            total += value;
        }

        if (total + diff < 0 || (total + diff) % 2 != 0) {
            return 0;
        }

        long long target = (total + diff) / 2;
        if (target < 0) {
            return 0;
        }

        vector<int> dp(static_cast<size_t>(target) + 1, 0);
        dp[0] = 1;

        for (int value : arr) {
            for (long long sum = target; sum >= value; --sum) {
                dp[sum] += dp[sum - value];
                if (dp[sum] >= MOD) {
                    dp[sum] -= MOD;
                }
            }
        }

        return dp[target];
    }
};
```

For example, with `arr = [1, 2, 3, 3]` and `diff = 2`, the total is 9, so the target is `(9 + 2) / 2`, which is not an integer. The answer is therefore 0.

Time complexity: `O(n * target)`.
Space complexity: `O(target)`.

Instead of allocating an array up to the target, this Go version stores counts in a map. It is handy when the reachable sums are much fewer than all values from zero to the target. A fresh map is built for every element, so the current number is not reused in the same step.

```go
func countPartitions(n int, diff int, arr []int) int {
	const mod int64 = 1000000007

	var total int64
	for _, value := range arr {
		total += int64(value)
	}

	needed := total + int64(diff)
	if needed < 0 || needed%2 != 0 {
		return 0
	}

	target := needed / 2
	counts := map[int64]int64{0: 1}

	for _, value := range arr {
		next := make(map[int64]int64, len(counts)*2)
		for sum, ways := range counts {
			next[sum] = (next[sum] + ways) % mod
			next[sum+int64(value)] = (next[sum+int64(value)] + ways) % mod
		}
		counts = next
	}

	return int(counts[target])
}
```

For an input such as `[0, 0, 1]`, the map keeps separate counts for the different choices of the zeroes. This is why zero values should not be removed before running the DP.

The trade-off is that map operations use more overhead than indexing a slice. The code is useful when the target range is large but the number of reachable sums stays small.

Time complexity: `O(n * k)` expected, where `k` is the number of stored sums.
Space complexity: `O(k)`.

This is a different option for smaller arrays. The array is split into two halves. I generate every subset sum in each half, count how often each sum occurs, and then match a left sum with `target - left sum` on the right.

```cpp
class Solution {
  public:
   int countPartitions(int n, int diff, vector<int>& arr) {
        const int MOD = 1000000007;
        long long total = 0;
        for (int value : arr) {
            total += value;
        }

        long long needed = total + diff;
        if (needed < 0 || needed % 2 != 0) {
            return 0;
        }

        long long target = needed / 2;
        int mid = n / 2;
        int leftSize = mid;
        int rightSize = n - mid;

        unordered_map<long long, int> rightCounts;
        int rightMasks = 1 << rightSize;
        for (int mask = 0; mask < rightMasks; mask++) {
            long long sum = 0;
            for (int bit = 0; bit < rightSize; bit++) {
                if (mask & (1 << bit)) {
                    sum += arr[mid + bit];
                }
            }
            rightCounts[sum]++;
        }

        long long answer = 0;
        int leftMasks = 1 << leftSize;
        for (int mask = 0; mask < leftMasks; mask++) {
            long long sum = 0;
            for (int bit = 0; bit < leftSize; bit++) {
                if (mask & (1 << bit)) {
                    sum += arr[bit];
                }
            }

            auto it = rightCounts.find(target - sum);
            if (it != rightCounts.end()) {
                answer = (answer + it->second) % MOD;
            }
        }

        return static_cast<int>(answer);
    }
};
```

For a quick dry run, split `[1, 2, 3, 3]` into `[1, 2]` and `[3, 3]`. If the target is 5, the left subset sum 2 matches the right subset sum 3, and the left subset sum 5 would match right sum 0 if it existed. The map handles these matches directly.

The method works well for around 30 to 40 elements, but it is not suitable for a large `n` because the number of subsets grows quickly.

Time complexity: `O(2^(n/2) * n)` with the simple subset generation used here.
Space complexity: `O(2^(n/2))`.

I used the same target-sum conversion, but kept the choices in a recursive function. At every index, the current value can either be placed in the selected group or skipped. The memo table saves repeated states `(index, remaining_sum)`.

```python
class Solution:
    def countPartitions(self, n, diff, arr):
        MOD = 1000000007
        total = sum(arr)
        needed = total + diff

        if needed < 0 or needed % 2 != 0:
            return 0

        target = needed // 2
        memo = {}

        def ways(index, remaining):
            if remaining == 0:
                return 1
            if index == n or remaining < 0:
                return 0

            state = (index, remaining)
            if state in memo:
                return memo[state]

            skip = ways(index + 1, remaining)
            take = ways(index + 1, remaining - arr[index])
            memo[state] = (skip + take) % MOD
            return memo[state]

        return ways(0, target)
```

The base case `remaining == 0` returns one way, even when there are zeroes left. That is important because each zero can be chosen or skipped and can create another valid partition.

A small dry run for `[1, 2, 3]` with difference `0`: the total is 6 and the target is 3. The recursion finds the subsets `{3}` and `{1, 2}`, so it returns 2.

Time complexity: `O(n * target)` memoized states.
Space complexity: `O(n * target)` for the memo table and recursion stack.

## Solution
```cpp[]
class Solution {
    int MOD = 1e9 + 7;

public:
    int countPartitions(int n, int diff, vector<int>& arr) {
        int total = accumulate(arr.begin(), arr.end(), 0);
        vector <vector <int>>dp(n+1 , vector<int>(total+1 , -1));
        return solve(0, n, diff, arr, total, total,dp);
    }

    int solve(int ind, int n, int diff,
              vector<int>& arr,
              int sum1,
              int total , vector <vector <int>> &dp) {

      if(dp[ind][sum1] != -1)return dp[ind][sum1];

        if (ind == n) {
            int sum2 = total - sum1;
            if(sum1 >= sum2 &&  sum1 - sum2 == diff)return 1;
            else return  0;
        }


        int take =
            solve(ind + 1, n, diff,
                  arr, sum1 - arr[ind], total, dp);

        int nottake =
            solve(ind + 1, n, diff,
                  arr, sum1, total, dp);

        return dp[ind][sum1] = (take + nottake) % MOD;
    }
};
```

## Complexity
**Time Complexity:** 
O(n* totalsum)

**Space Complexity:**
O(n* totalsum) + O(n)--recursion stack
